import{_ as t,a0 as o,w as r,s as d,I as a,x as n,a1 as p,A as i,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const M=JSON.parse('{"title":"在 Ubuntu 16.04 下隨機化你的 WiFi MAC 地址 | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu 16.04 下隨機化你的 WiFi MAC 地址 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu 16.04 下隨機化你的 WiFi MAC 地址 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu 16.04 下隨機化你的 WiFi MAC 地址 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171201 Randomize your WiFi MAC address on Ubuntu 16.04","title":"在 Ubuntu 16.04 下隨機化你的 WiFi MAC 地址","tag":"201712","desc":""},"relativePath":"201712/20171201 Randomize your WiFi MAC address on Ubuntu 16.04.md","filePath":"[post].md"}'),u={name:"201712/20171201 Randomize your WiFi MAC address on Ubuntu 16.04.md"};function f(m,s,g,b,c,C){const e=o("Link");return r(),d("div",null,[s[36]||(s[36]=a("h1",{id:"在-ubuntu-16-04-下隨機化你的-wifi-mac-地址",tabindex:"-1"},[n("在 Ubuntu 16.04 下隨機化你的 WiFi MAC 地址 "),a("a",{class:"header-anchor",href:"#在-ubuntu-16-04-下隨機化你的-wifi-mac-地址","aria-label":"Permalink to “在 Ubuntu 16.04 下隨機化你的 WiFi MAC 地址”"},"​")],-1)),s[37]||(s[37]=a("blockquote",null,[a("p",null,"你的設備的 MAC 地址可以在不同的 WiFi 網絡中記錄你的活動。這些信息能被共享後出售，用於識別特定的個體。但可以用隨機生成的偽 MAC 地址來阻止這一行為。")],-1)),s[38]||(s[38]=a("p",null,[a("img",{src:"https://www.paulfurley.com/img/captive-portal-our-hotel.gif",alt:"A captive portal screen for a hotel allowing you to log in with social media for an hour of free WiFi"})],-1)),a("p",null,[a("em",null,[s[1]||(s[1]=n("Image courtesy of ",-1)),p(e,{href:"http://cloudessa.com/products/cloudessa-aaa-and-captive-portal-cloud-service/"},{default:i(()=>[...s[0]||(s[0]=[n("Cloudessa",-1)])]),_:1})])]),s[39]||(s[39]=l('<p>每一個諸如 WiFi 或者以太網卡這樣的網絡設備，都有一個叫做 MAC 地址的唯一標識符，如：<code>b4:b6:76:31:8c:ff</code>。這就是你能上網的原因：每當你連上 WiFi，路由器就會用這一地址來向你接受和發送數據，並且用它來區別你和這一網絡的其它設備。</p><p>這一設計的缺陷在於唯一性，不變的 MAC 地址正好可以用來追蹤你。連上了星巴克的 WiFi? 好，注意到了。在倫敦的地鐵上? 也記錄下來。</p><p>如果你曾經在某一個 WiFi 驗證頁面上輸入過你的真實姓名，你就已經把自己和這一 MAC 地址建立了聯繫。沒有仔細閲讀許可服務條款、你可以認為，機場的免費 WiFi 正通過出售所謂的 ‘顧客分析數據’（你的個人信息）獲利。出售的對象包括酒店，餐飲業，和任何想要了解你的人。</p><p>我不想信息被記錄，再出售給多家公司，所以我花了幾個小時想出了一個解決方案。</p><h3 id="mac-地址不一定總是不變的" tabindex="-1">MAC 地址不一定總是不變的 <a class="header-anchor" href="#mac-地址不一定總是不變的" aria-label="Permalink to “MAC 地址不一定總是不變的”">​</a></h3><p>幸運的是，在不斷開網絡的情況下，是可以隨機生成一個偽 MAC 地址的。</p><p>我想隨機生成我的 MAC 地址，但是有三個要求：</p><ol><li>MAC 地址在不同網絡中是不相同的。這意味着，我在星巴克和在倫敦地鐵網絡中的 MAC 地址是不相同的，這樣在不同的服務提供商中就無法將我的活動系起來。</li><li>MAC 地址需要經常更換，這樣在網絡上就沒人知道我就是去年在這兒經過了 75 次的那個人。</li><li>MAC 地址一天之內應該保持不變。當 MAC 地址更改時，大多數網絡都會與你斷開連接，然後必須得進入驗證頁面再次登陸 - 這很煩人。</li></ol><h3 id="操作網絡管理器networkmanager" tabindex="-1">操作<ruby>網絡管理器<rt>NetworkManager</rt></ruby> <a class="header-anchor" href="#操作網絡管理器networkmanager" aria-label="Permalink to “操作網絡管理器NetworkManager”">​</a></h3><p>我第一次嘗試用一個叫做 <code>macchanger</code> 的工具，但是失敗了。因為<ruby>網絡管理器<rt>NetworkManager</rt></ruby>會根據它自己的設置恢復默認的 MAC 地址。</p>',10)),a("p",null,[s[3]||(s[3]=n("我瞭解到，網絡管理器 1.4.1 以上版本可以自動生成隨機的 MAC 地址。如果你在使用 Ubuntu 17.04 版本，你可以根據",-1)),p(e,{href:"https://gist.github.com/paulfurley/978d4e2e0cceb41d67d017a668106c53/"},{default:i(()=>[...s[2]||(s[2]=[n("這一配置文件",-1)])]),_:1}),s[4]||(s[4]=n("實現這一目的。但這並不能完全符合我的三個要求（你必須在",-1)),s[5]||(s[5]=a("ruby",null,[n("隨機"),a("rt",null,"random")],-1)),s[6]||(s[6]=n("和",-1)),s[7]||(s[7]=a("ruby",null,[n("穩定"),a("rt",null,"stable")],-1)),s[8]||(s[8]=n("這兩個選項之中選擇一個，但沒有一天之內保持不變這一選項）",-1))]),s[40]||(s[40]=l(`<p>因為我使用的是 Ubuntu 16.04，網絡管理器版本為 1.2，不能直接使用高版本這一新功能。可能網絡管理器有一些隨機化方法支持，但我沒能成功。所以我編了一個腳本來實現這一目標。</p><p>幸運的是，網絡管理器 1.2 允許模擬 MAC 地址。你在已連接的網絡中可以看見 ‘編輯連接’ 這一選項：</p><p><img src="https://www.paulfurley.com/img/network-manager-cloned-mac-address.png" alt="Screenshot of NetworkManager&#39;s edit connection dialog, showing a text entry for a cloned mac address"></p><p>網絡管理器也支持鈎子處理 —— 任何位於 <code>/etc/NetworkManager/dispatcher.d/pre-up.d/</code> 的腳本在建立網絡連接之前都會被執行。</p><h3 id="分配隨機生成的偽-mac-地址" tabindex="-1">分配隨機生成的偽 MAC 地址 <a class="header-anchor" href="#分配隨機生成的偽-mac-地址" aria-label="Permalink to “分配隨機生成的偽 MAC 地址”">​</a></h3><p>我想根據網絡 ID 和日期來生成新的隨機 MAC 地址。 我們可以使用網絡管理器的命令列工具 nmcli 來顯示所有可用網絡：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; nmcli connection</span></span>
<span class="line"><span>NAME                 UUID                                  TYPE             DEVICE</span></span>
<span class="line"><span>Gladstone Guest      618545ca-d81a-11e7-a2a4-271245e11a45  802-11-wireless  wlp1s0</span></span>
<span class="line"><span>DoESDinky            6e47c080-d81a-11e7-9921-87bc56777256  802-11-wireless  --</span></span>
<span class="line"><span>PublicWiFi           79282c10-d81a-11e7-87cb-6341829c2a54  802-11-wireless  --</span></span>
<span class="line"><span>virgintrainswifi     7d0c57de-d81a-11e7-9bae-5be89b161d22  802-11-wireless  --</span></span></code></pre></div><p>因為每個網絡都有一個唯一標識符（UUID），為了實現我的計劃，我將 UUID 和日期拼接在一起，然後使用 MD5 生成 hash 值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># eg 618545ca-d81a-11e7-a2a4-271245e11a45-2017-12-03</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt; echo -n &quot;\${UUID}-$(date +%F)&quot; | md5sum</span></span>
<span class="line"><span></span></span>
<span class="line"><span>53594de990e92f9b914a723208f22b3f  -</span></span></code></pre></div><p>生成的結果可以代替 MAC 地址的最後八個字節。</p>`,10)),a("p",null,[s[10]||(s[10]=n("值得注意的是，最開始的字節 ",-1)),s[11]||(s[11]=a("code",null,"02",-1)),s[12]||(s[12]=n(" 代表這個地址是",-1)),p(e,{href:"https://en.wikipedia.org/wiki/MAC_address#Universal_vs._local"},{default:i(()=>[...s[9]||(s[9]=[n("自行指定",-1)])]),_:1}),s[13]||(s[13]=n("的。實際上，真實 MAC 地址的前三個字節是由製造商決定的，例如 ",-1)),s[14]||(s[14]=a("code",null,"b4:b6:76",-1)),s[15]||(s[15]=n(" 就代表 Intel。",-1))]),s[41]||(s[41]=l(`<p>有可能某些路由器會拒絕自己指定的 MAC 地址，但是我還沒有遇到過這種情況。</p><p>每次連接到一個網絡，這一腳本都會用 <code>nmcli</code> 來指定一個隨機生成的偽 MAC 地址：</p><p><img src="https://www.paulfurley.com/imgterminal-window-nmcli-commands.png" alt="A terminal window show a number of nmcli command line calls"></p><p>最後，我查看了 <code>ifconfig</code> 的輸出結果，我發現 MAC 地址 <code>HWaddr</code> 已經變成了隨機生成的地址（模擬 Intel 的），而不是我真實的 MAC 地址。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; ifconfig</span></span>
<span class="line"><span>wlp1s0    Link encap:Ethernet  HWaddr b4:b6:76:45:64:4d</span></span>
<span class="line"><span>          inet addr:192.168.0.86  Bcast:192.168.0.255  Mask:255.255.255.0</span></span>
<span class="line"><span>          inet6 addr: fe80::648c:aff2:9a9d:764/64 Scope:Link</span></span>
<span class="line"><span>          UP BROADCAST RUNNING MULTICAST  MTU:1500  Metric:1</span></span>
<span class="line"><span>          RX packets:12107812 errors:0 dropped:2 overruns:0 frame:0</span></span>
<span class="line"><span>          TX packets:18332141 errors:0 dropped:0 overruns:0 carrier:0</span></span>
<span class="line"><span>          collisions:0 txqueuelen:1000</span></span>
<span class="line"><span>          RX bytes:11627977017 (11.6 GB)  TX bytes:20700627733 (20.7 GB)</span></span></code></pre></div><h3 id="腳本" tabindex="-1">腳本 <a class="header-anchor" href="#腳本" aria-label="Permalink to “腳本”">​</a></h3>`,6)),a("p",null,[s[17]||(s[17]=n("完整的腳本也可以",-1)),p(e,{href:"https://gist.github.com/paulfurley/46e0547ce5c5ea7eabeaef50dbacef3f"},{default:i(()=>[...s[16]||(s[16]=[n("在 Github 上查看",-1)])]),_:1}),s[18]||(s[18]=n("。",-1))]),s[42]||(s[42]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span># /etc/NetworkManager/dispatcher.d/pre-up.d/randomize-mac-addresses</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Configure every saved WiFi connection in NetworkManager with a spoofed MAC</span></span>
<span class="line"><span># address, seeded from the UUID of the connection and the date eg:</span></span>
<span class="line"><span># &#39;c31bbcc4-d6ad-11e7-9a5a-e7e1491a7e20-2017-11-20&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># This makes your MAC impossible(?) to track across WiFi providers, and</span></span>
<span class="line"><span># for one provider to track across days.</span></span>
<span class="line"><span></span></span>
<span class="line"><span># For craptive portals that authenticate based on MAC, you might want to</span></span>
<span class="line"><span># automate logging in :)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Note that NetworkManager &gt;= 1.4.1 (Ubuntu 17.04+) can do something similar</span></span>
<span class="line"><span># automatically.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export PATH=$PATH:/usr/bin:/bin</span></span>
<span class="line"><span></span></span>
<span class="line"><span>LOG_FILE=/var/log/randomize-mac-addresses</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo &quot;$(date): $*&quot; &gt; \${LOG_FILE}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>WIFI_UUIDS=$(nmcli --fields type,uuid connection show |grep 802-11-wireless |cut &#39;-d &#39; -f3)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>for UUID in \${WIFI_UUIDS}</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>    UUID_DAILY_HASH=$(echo &quot;\${UUID}-$(date +F)&quot; | md5sum)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    RANDOM_MAC=&quot;02:$(echo -n \${UUID_DAILY_HASH} | sed &#39;s/^\\(..\\)\\(..\\)\\(..\\)\\(..\\)\\(..\\).*$/\\1:\\2:\\3:\\4:\\5/&#39;)&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    CMD=&quot;nmcli connection modify \${UUID} wifi.cloned-mac-address \${RANDOM_MAC}&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    echo &quot;$CMD&quot; &gt;&gt; \${LOG_FILE}</span></span>
<span class="line"><span>    $CMD &amp;</span></span>
<span class="line"><span>done</span></span>
<span class="line"><span></span></span>
<span class="line"><span>wait</span></span></code></pre></div>`,1)),a("p",null,[a("em",null,[s[21]||(s[21]=n("更新：",-1)),p(e,{href:"https://gist.github.com/paulfurley/46e0547ce5c5ea7eabeaef50dbacef3f/revisions#diff-824d510864d58c07df01102a8f53faef"},{default:i(()=>[...s[19]||(s[19]=[n("使用自己指定的 MAC 地址",-1)])]),_:1}),s[22]||(s[22]=n("可以避免和真正的 intel 地址衝突。感謝 ",-1)),p(e,{href:"https://twitter.com/fink_/status/937305600005943296"},{default:i(()=>[...s[20]||(s[20]=[n("@_fink",-1)])]),_:1})])]),s[43]||(s[43]=a("hr",null,null,-1)),a("p",null,[s[24]||(s[24]=n("via: ",-1)),p(e,{href:"https://www.paulfurley.com/randomize-your-wifi-mac-address-on-ubuntu-1604-xenial/"},{default:i(()=>[...s[23]||(s[23]=[n("https://www.paulfurley.com/randomize-your-wifi-mac-address-on-ubuntu-1604-xenial/",-1)])]),_:1})]),a("p",null,[s[28]||(s[28]=n("作者：",-1)),p(e,{href:"https://www.paulfurley.com/"},{default:i(()=>[...s[25]||(s[25]=[n("Paul M Furley",-1)])]),_:1}),s[29]||(s[29]=n(" 譯者：",-1)),p(e,{href:"https://github.com/wenwensnow"},{default:i(()=>[...s[26]||(s[26]=[n("wenwensnow",-1)])]),_:1}),s[30]||(s[30]=n(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[27]||(s[27]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[33]||(s[33]=n("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[31]||(s[31]=[n("LCTT",-1)])]),_:1}),s[34]||(s[34]=n(" 原創編譯，",-1)),p(e,{href:"https://linux.cn/"},{default:i(()=>[...s[32]||(s[32]=[n("Linux中國",-1)])]),_:1}),s[35]||(s[35]=n(" 榮譽推出",-1))])])}const w=t(u,[["render",f]]);export{M as __pageData,w as default};
